FUNCTION_BLOCK FB
VAR_INPUT
    THICKNESS_FAULT: BOOL;
    THICKNESS_SIGNAL_VALID: BOOL;
    CUTTING_RUN: BOOL;
    FaultTimestamp: DINT;
    CycleTime: TIME;
END_VAR

VAR_OUTPUT
    THICKNESS_ALARM: BOOL;
    Slab_Fault_Counter: UINT;
    Slab_Runtime_Accumulator: LINT;
    Slab_Fault_History: ARRAY[0..4] OF DINT;
END_VAR

VAR
    AlarmHoldScans: INT := 0;
    PrevValidFault: BOOL := FALSE;
    // Possibly also track previous signal valid? Not needed.
END_VAR

// Main scan logic
// Compute current combined fault condition
VAR
    CurrValidFault: BOOL;
END_VAR

CurrValidFault := THICKNESS_SIGNAL_VALID AND THICKNESS_FAULT;

// If signal invalid, clear alarm and hold, and also set outputs accordingly
IF NOT THICKNESS_SIGNAL_VALID THEN
    THICKNESS_ALARM := FALSE;
    AlarmHoldScans := 0;
    // Do not update fault counter, runtime, history
    // We need to set PrevValidFault for next scan? We can set PrevValidFault := FALSE; because no valid fault.
    PrevValidFault := FALSE;
ELSE
    // Signal valid
    // Handle fault rising edge: increment counter and shift history
    IF CurrValidFault AND NOT PrevValidFault THEN
        // Rising edge of valid fault
        // Increment fault counter if not at max
        IF Slab_Fault_Counter < UINT#65535 THEN
            Slab_Fault_Counter := Slab_Fault_Counter + UINT#1;
        END_IF
        // Shift history: move each entry down
        Slab_Fault_History[4] := Slab_Fault_History[3];
        Slab_Fault_History[3] := Slab_Fault_History[2];
        Slab_Fault_History[2] := Slab_Fault_History[1];
        Slab_Fault_History[1] := Slab_Fault_History[0];
        Slab_Fault_History[0] := FaultTimestamp;
    END_IF

    // Handle fault clearing: start hold if fault was true and now false
    // Actually we want to start hold when fault clears (i.e., when PrevValidFault = TRUE and CurrValidFault = FALSE)
    IF PrevValidFault AND NOT CurrValidFault THEN
        // Fault cleared, start hold for 25 scans
        AlarmHoldScans := 25;
    END_IF

    // Update alarm output: true if fault present or hold active
    // If fault present, alarm true; else if hold > 0, alarm true; else false
    IF THICKNESS_FAULT THEN
        THICKNESS_ALARM := TRUE;
        // Optionally reset hold? Not needed; keep hold count as is (or set to 0)
        // But we might want to set AlarmHoldScans := 0 if fault present, but not required.
    ELSIF AlarmHoldScans > 0 THEN
        THICKNESS_ALARM := TRUE;
        // Decrement hold counter
        AlarmHoldScans := AlarmHoldScans - 1;
    ELSE
        THICKNESS_ALARM := FALSE;
    END_IF

    // If we want to keep hold count when fault present, we can do nothing.
    // But note: If fault persists, we want alarm true, but we also want to keep hold count? Not needed.
    // However, if we want to maintain hold count for after fault clears, we should not decrement when fault present.
    // In our logic above, we decrement only when fault absent and hold > 0. That's correct.

    // Now runtime accumulation
    IF CUTTING_RUN AND NOT THICKNESS_FAULT THEN
        // Condition: valid signal (already known) and no fault
        Slab_Runtime_Accumulator := Slab_Runtime_Accumulator + LINT#1;
    END_IF

    // Update PrevValidFault for next scan
    PrevValidFault := CurrValidFault;
END_IF

// End of function block
END_FUNCTION_BLOCK
